// Chạy theo lịch (7 ngày) hoặc theo nút bấm trên WordPress (7 hoặc 30 ngày).
const j = $input.first().json;
const days = [7, 30].includes(Number(j.body?.days)) ? Number(j.body.days) : 7;
const source = j.body ? 'nút bấm trên WordPress' : 'lịch thứ Hai 08:00';
console.log('[socialsync] Bắt đầu báo cáo', JSON.stringify({ days, source, request_id: j.body?.request_id ?? null }));
return [{ json: { days, source, request_id: j.body?.request_id ?? null } }];

// Gom mã bài Facebook để đọc tương tác bằng MỘT lần gọi Graph API (?ids=...), tiết kiệm hạn mức app.
const r = $input.first().json;
if (r.statusCode !== 200 || !r.body || r.body.ok !== true) {
  throw new Error(`Không lấy được số liệu từ WordPress: HTTP ${r.statusCode} ${JSON.stringify(r.body).slice(0, 300)}`);
}
const posts = r.body.facebook_posts ?? [];
console.log('[socialsync] Số bài Facebook cần đọc tương tác', posts.length);
return [{ json: { has_posts: posts.length > 0, ids: posts.map(p => p.remote_id).join(','), posts } }];

// Graph Batch API: một request, mỗi bài một kết quả {code, body}. (Tham số ?ids= bị Facebook bỏ từ v26.)
const r = $input.first().json;
const posts = $('Chuẩn bị đọc tương tác').first().json.posts;
const headers = r.headers ?? {};
if (r.statusCode !== 200 || !Array.isArray(r.body)) {
  console.log('[socialsync] Facebook batch lỗi', JSON.stringify({ status: r.statusCode ?? null, body: r.body ?? null, error: r.error?.message ?? null }));
  return [{ json: { ok: false, items: [], error: `Facebook HTTP ${r.statusCode}: ${JSON.stringify(r.body?.error ?? r.body ?? r.error).slice(0, 300)}`, usage: headers['x-app-usage'] ?? null } }];
}
const items = [];
const errors = [];
r.body.forEach((res, i) => {
  const p = posts[i];
  let b = {};
  try { b = JSON.parse(res?.body ?? '{}'); } catch (e) { /* giữ rỗng */ }
  if (res?.code !== 200) { errors.push(b.error?.message ?? `HTTP ${res?.code}`); return; }
  items.push({ job_id: p.job_id, title: p.title, metrics: {
    reactions: b.reactions?.summary?.total_count ?? 0,
    comments: b.comments?.summary?.total_count ?? 0,
    shares: b.shares?.count ?? 0,
  } });
});
const needPerm = errors.some(e => /pages_read_user_content/.test(e));
const error = errors.length ? `${errors.length}/${posts.length} bài không đọc được tương tác${needPerm ? ': app Facebook cần thêm quyền pages_read_user_content' : ': ' + errors[0]}` : null;
console.log('[socialsync] Tương tác Facebook', JSON.stringify({ ok_items: items.length, errors: errors.length, need_permission: needPerm, usage: headers['x-app-usage'] ?? null }));
return [{ json: { ok: errors.length === 0, items, error, usage: headers['x-app-usage'] ?? null } }];

// Gom số liệu + tương tác, dựng yêu cầu cho Claude viết báo cáo ngắn cho trưởng phòng Marketing.
const prep = $('Chuẩn bị').first().json;
const stats = $('Lấy số liệu từ WordPress').first().json.body;
let fb = { ok: false, items: [], error: 'Không có bài Facebook trong kỳ' };
try { fb = $('Facebook: tính tương tác').first().json; } catch (e) { /* nhánh không có bài Facebook */ }
const top = [...(fb.items ?? [])].sort((a, b) => (b.metrics.reactions + b.metrics.comments + b.metrics.shares) - (a.metrics.reactions + a.metrics.comments + a.metrics.shares)).slice(0, 5);
const data = {
  so_ngay: prep.days,
  tong_luot: stats.jobs,
  theo_kenh: Object.values(stats.channels).map(c => ({ kenh: c.label, tong: c.total, da_dang: c.published, loi: c.failed, ti_le_thanh_cong: c.success_rate, tb_phut_tu_xuat_ban_toi_len_kenh: c.avg_lead_min, trang_thai_khac: c.by_status })),
  phan_loai: stats.classification,
  nguon_noi_dung: stats.content_source,
  ai: stats.ai,
  bai_tuong_tac_cao_nhat_facebook: top.map(t => ({ tieu_de: t.title, ...t.metrics })),
  ghi_chu: fb.ok ? null : fb.error,
};
const SYSTEM = [
  'Viết báo cáo tuần ngắn (tối đa 200 từ, tiếng Việt) cho trưởng phòng Marketing về hệ thống tự động đồng bộ nội dung website lên Facebook và Pinterest.',
  'Chỉ dùng số trong dữ liệu. Không suy diễn nguyên nhân khi dữ liệu không cho biết. Không dùng markdown, chỉ văn bản thường với gạch đầu dòng "-".',
  'Cấu trúc: 1) Kết quả chính (số bài, tỉ lệ thành công từng kênh). 2) Lỗi và việc chờ xử lý (chờ duyệt, lỗi). 3) Bài có tương tác cao nhất. 4) Việc cần người quyết định (nếu có).',
].join('\n');
const request_body = {
  model: 'claude-opus-5-5',
  max_tokens: 4000,
  fallbacks: 'default',
  output_config: { effort: 'low' },
  system: SYSTEM,
  messages: [{ role: 'user', content: 'Số liệu (JSON):\n' + JSON.stringify(data, null, 2) }],
};
console.log('[socialsync] Gửi Claude tóm tắt báo cáo', JSON.stringify({ days: prep.days, jobs: stats.jobs, top: top.length }));
return [{ json: { request_body, data, started_ms: Date.now() } }];

// Claude lỗi thì vẫn lưu báo cáo dạng số liệu thô, kèm lý do.
const r = $input.first().json;
const prep = $('Dựng yêu cầu tóm tắt').first().json;
const d = prep.data;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ chuỗi */ } }
const text = r.statusCode === 200 && body && body.stop_reason === 'end_turn' ? (body.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('').trim() : '';
let out;
if (text) {
  out = { summary: text, source: 'ai', model: body.model, error: null };
} else {
  const lines = [`Báo cáo ${d.so_ngay} ngày (số liệu thô):`];
  for (const k of d.theo_kenh) lines.push(`- ${k.kenh}: ${k.da_dang} đã đăng, ${k.loi} lỗi, tỉ lệ thành công ${k.ti_le_thanh_cong ?? '—'}%`);
  lines.push(`- Lần gọi AI: ${d.ai.calls}, chi phí ước tính $${d.ai.usd_estimate}`);
  out = { summary: lines.join('\n'), source: 'raw', model: null, error: `Claude không tóm tắt được: HTTP ${r.statusCode ?? '—'} ${JSON.stringify(body?.error ?? r.error?.message ?? body?.stop_reason ?? '').slice(0, 300)}` };
}
console.log('[socialsync] Báo cáo', JSON.stringify({ source: out.source, chars: out.summary.length, ms: Date.now() - prep.started_ms, usage: body?.usage ?? null }));
return [{ json: { ...out, days: d.so_ngay, execution_id: $execution.id } }];
